import { createContext, useContext, useEffect, useReducer } from 'react'
import type { DemoAction, DemoState, DemoTask } from './types'
import { demoTask, initialState, nodeFixtures } from './fixtures'

export const STORAGE_KEY = 'capacity-demo:v1'
const now = () => new Date().toISOString().slice(0, 16).replace('T', ' ')
const addAudit = (state: DemoState, label: string): DemoState => ({ ...state, audit: [{ id: `AUD-${state.audit.length + 1}`, label, at: now() }, ...state.audit].slice(0, 12) })

export function reducer(state: DemoState, action: DemoAction): DemoState {
  switch (action.type) {
    case 'setRole': return addAudit({ ...state, role: action.role }, `切换角色：${action.role}`)
    case 'setScenario': return addAudit({ ...state, scenario: action.scenario }, `切换场景：${action.scenario}`)
    case 'setQuery': return { ...state, query: action.query }
    case 'setKnowledgeQuery': return { ...state, knowledgeQuery: action.query }
    case 'reset': return initialState
    case 'createTask': {
      const task: DemoTask = { id: `TASK-${Date.now().toString().slice(-6)}`, name: action.name, well: action.well, status: 'draft', version: 1, createdAt: now(), nodes: nodeFixtures.map((node, index) => ({ ...node, status: index === 0 ? 'confirmed' : 'pending' })) }
      return addAudit({ ...state, tasks: [task, ...state.tasks], activeTaskId: task.id }, `创建任务：${action.name}`)
    }
    case 'setTaskStatus': return addAudit({ ...state, tasks: state.tasks.map(task => task.id === action.taskId ? { ...task, status: action.status, version: task.version + 1 } : task) }, `任务状态：${action.status}`)
    case 'confirmNode': return addAudit({ ...state, tasks: state.tasks.map(task => task.id === action.taskId ? { ...task, status: 'running', nodes: task.nodes.map((node, index) => node.id === action.nodeId ? { ...node, status: 'confirmed' } : index === task.nodes.findIndex(n => n.id === action.nodeId) + 1 && node.status === 'pending' ? { ...node, status: 'running' } : node) } : task) }, `确认节点：${action.nodeId}`)
    case 'rejectTask': return addAudit({ ...state, tasks: state.tasks.map(task => task.id === action.taskId ? { ...task, status: 'rejected', rejection: action.reason, version: task.version + 1 } : task) }, '审核驳回，生成修改草稿')
    case 'resubmitTask': return addAudit({ ...state, tasks: state.tasks.map(task => task.id === action.taskId ? { ...task, status: 'review', version: task.version + 1, rejection: undefined } : task) }, '修改后重新提交审核')
  }
}

const StateContext = createContext<{ state: DemoState; dispatch: React.Dispatch<DemoAction> } | null>(null)
export function DemoProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(reducer, initialState, () => {
    try { const saved = localStorage.getItem(STORAGE_KEY); return saved ? JSON.parse(saved) as DemoState : initialState } catch { return initialState }
  })
  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)) }, [state])
  return <StateContext.Provider value={{ state, dispatch }}>{children}</StateContext.Provider>
}
export function useDemo() { const value = useContext(StateContext); if (!value) throw new Error('DemoProvider is missing'); return value }

export type DemoRole = 'engineer' | 'reviewer' | 'manager' | 'knowledge' | 'asset' | 'admin'
export type ScenarioMode = 'normal' | 'loading' | 'empty' | 'error' | 'unauthorized' | 'boundary'
export type TaskStatus = 'draft' | 'running' | 'paused' | 'cancelled' | 'review' | 'rejected' | 'approved'
export type NodeStatus = 'pending' | 'running' | 'confirmed' | 'blocked' | 'cancelled'
export type PageId = 'workspace' | 'new-task' | 'flow' | 'analysis' | 'trace' | 'assets' | 'reports' | 'knowledge' | 'ask' | 'admin'

export interface TaskNode { id: string; label: string; func: string; status: NodeStatus; note?: string }
export interface DemoTask { id: string; name: string; well: string; status: TaskStatus; version: number; createdAt: string; nodes: TaskNode[]; rejection?: string }
export interface AuditEvent { id: string; label: string; at: string }
export interface DemoState { role: DemoRole; scenario: ScenarioMode; tasks: DemoTask[]; activeTaskId: string; audit: AuditEvent[]; query: string; knowledgeQuery: string; }
export type DemoAction =
  | { type: 'setRole'; role: DemoRole }
  | { type: 'setScenario'; scenario: ScenarioMode }
  | { type: 'createTask'; name: string; well: string }
  | { type: 'setTaskStatus'; taskId: string; status: TaskStatus }
  | { type: 'confirmNode'; taskId: string; nodeId: string }
  | { type: 'setQuery'; query: string }
  | { type: 'setKnowledgeQuery'; query: string }
