const nav = [
  { to: '/workspace', page: 'workspace' as PageId, label: '工作台', icon: Home },
  { to: '/assets', page: 'assets' as PageId, label: '资产目录', icon: Layers3 },
  { to: '/reports', page: 'reports' as PageId, label: '报告中心', icon: FileText },
  { to: '/knowledge', page: 'knowledge' as PageId, label: '知识检索', icon: BookOpen },
  { to: '/ask', page: 'ask' as PageId, label: '智能问数', icon: BarChart3 },
