function App() {
  return <Routes><Route element={<Shell />}>
    <Route path="/workspace" element={<Workspace />} /><Route path="/tasks/new" element={<NewTask />} />
    <Route path="/tasks/:id/flow" element={<Flow />} /><Route path="/tasks/:id/analysis" element={<Analysis />} /><Route path="/tasks/:id/trace" element={<Trace />} />
    <Route path="/assets" element={<Assets />} /><Route path="/reports" element={<Reports />} /><Route path="/knowledge" element={<Knowledge />} /><Route path="/ask" element={<Ask />} /><Route path="/admin" element={<Admin />} />
    <Route path="*" element={<Navigate to="/workspace" replace />} />
  </Route></Routes>
