function Shell() {
  const location = useLocation(); const { state, dispatch } = useDemo(); const [open, setOpen] = useState(false)
  const activePage: PageId = location.pathname.startsWith('/tasks/new') ? 'new-task' : location.pathname.startsWith('/tasks/') ? (location.pathname.includes('/analysis') ? 'analysis' : location.pathname.includes('/trace') ? 'trace' : 'flow') : (location.pathname.slice(1) as PageId) || 'workspace'
  const allowed = rolePages[state.role]
  return <div className="app-shell">
    <aside className={`sidebar ${open ? 'is-open' : ''}`} aria-label="主导航"><div className="brand"><div className="brand-mark"><Gauge size={18} /></div><div><strong>产能评价</strong><span>工程工作台 · Demo</span></div></div>
      <nav>{nav.map(item => allowed.includes(item.page) ? <NavLink key={item.to} to={item.to} className={({ isActive }) => isActive ? 'nav-item active' : 'nav-item'} onClick={() => setOpen(false)}><item.icon size={17} /><span>{item.label}</span>{item.page === 'workspace' && state.tasks.some(task => task.status === 'review') ? <i className="nav-badge">1</i> : null}</NavLink> : null)}</nav>
      <div className="sidebar-foot"><div className="small-label">演示约束</div><p>本地 Mock · 不接真实服务</p><p>版本键 `capacity-demo:v1`</p></div>
    </aside>
    <main className="main-shell"><header className="topbar"><button className="icon-btn menu-btn" aria-label="打开导航" onClick={() => setOpen(value => !value)}><Menu size={19} /></button><div className="crumb">产品主线 <ChevronRight size={14} /> <span>{pageTitle(activePage)}</span></div><div className="top-actions"><label className="compact-control">角色<select aria-label="演示角色" value={state.role} onChange={event => dispatch({ type: 'setRole', role: event.target.value as DemoRole })}>{roleOptions.map(role => <option key={role} value={role}>{roleLabels[role]}</option>)}</select></label><label className="compact-control">场景<select aria-label="演示场景" value={state.scenario} onChange={event => dispatch({ type: 'setScenario', scenario: event.target.value as ScenarioMode })}>{scenarioOptions.map(scenario => <option key={scenario} value={scenario}>{scenarioLabels[scenario]}</option>)}</select></label><button className="icon-btn" title="重置 Demo" aria-label="重置 Demo" onClick={() => dispatch({ type: 'reset' })}><RotateCcw size={17} /></button></div></header><div className="page-wrap"><Routes><Route path="/workspace" element={<Workspace />} /><Route path="/tasks/new" element={<NewTask />} /><Route path="/tasks/:id/flow" element={<Flow />} /><Route path="/tasks/:id/analysis" element={<Analysis />} /><Route path="/tasks/:id/trace" element={<Trace />} /><Route path="/assets" element={<Assets />} /><Route path="/reports" element={<Reports />} /><Route path="/knowledge" element={<Knowledge />} /><Route path="/ask" element={<Ask />} /><Route path="/admin" element={<Admin />} /></Routes></div></main>
  </div>
}

function pageTitle(page: PageId) { return ({ workspace: '工作台', 'new-task': '新建评价任务', flow: '评价流程', analysis: '图表与分析', trace: '版本与溯源', assets: '资产目录', reports: '报告中心', knowledge: '知识检索', ask: '智能问数', admin: '系统管理' } satisfies Record<PageId, string>)[page] || '工作台' }
function StateBanner() { const { state } = useDemo(); if (state.scenario === 'normal') return null; const content = { loading: ['loading', '正在加载授权范围与 Demo 数据'], empty: ['info', '当前筛选没有可展示数据'], error: ['error', 'Demo 模拟服务异常，可重试或切换场景'], unauthorized: ['warning', '当前角色没有访问该资源的权限'], boundary: ['warning', '边界数据：公式、敏感性和报告结论保持 TBD'] }[state.scenario]; return <div className={`state-banner ${content[0]}`} role="status"><AlertTriangle size={16} /><span>{content[1]}</span></div> }
function Page({ title, eyebrow, actions, children }: { title: string; eyebrow: string; actions?: ReactNode; children: ReactNode }) { return <><StateBanner /><div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1></div>{actions && <div className="page-actions">{actions}</div>}</div>{children}</> }
function Panel({ title, meta, children, className = '' }: { title: string; meta?: string; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-head"><h2>{title}</h2>{meta && <span className="muted">{meta}</span>}</div>{children}</section> }
function Status({ status }: { status: TaskStatus }) { const map: Record<TaskStatus, [string, string]> = { draft: ['草稿', 'neutral'], running: ['进行中', 'blue'], paused: ['已暂停', 'amber'], cancelled: ['已取消', 'neutral'], review: ['待审核', 'purple'], rejected: ['已驳回', 'red'], approved: ['已批准', 'green'] }; const [label, tone] = map[status]; return <span className={`status ${tone}`}><span className="status-dot" />{label}</span> }

function Workspace() { const { state } = useDemo(); const navigate = useNavigate(); const task = state.tasks.find(item => item.id === state.activeTaskId) || state.tasks[0]; return <Page eyebrow="PAGE-001 · REQ-003/004/012" title="产能评价工作台" actions={<button className="button primary" onClick={() => navigate('/tasks/new')}><Play size={16} />新建任务</button>}><div className="metric-row"><div><span>授权任务</span><strong>{state.tasks.length}</strong><small>本地 Demo fixtures</small></div><div><span>待审核</span><strong>{state.tasks.filter(item => item.status === 'review').length}</strong><small>需要审核人处理</small></div><div><span>已确认节点</span><strong>{task?.nodes.filter(node => node.status === 'confirmed').length ?? 0}<em>/7</em></strong><small>公式与结果仍为 TBD</small></div><div><span>证据链</span><strong>6</strong><small>数据 · 资产 · 节点 · 引用 · 决定 · 版本</small></div></div><div className="workspace-grid"><Panel title="我的评价任务" meta="仅显示授权范围"><div className="table-wrap"><table><thead><tr><th>任务</th><th>目标井</th><th>状态</th><th>版本</th><th>操作</th></tr></thead><tbody>{state.tasks.map(item => <tr key={item.id}><td><strong>{item.name}</strong><small>{item.id} · {item.createdAt}</small></td><td>{item.well}</td><td><Status status={item.status} /></td><td>v{item.version}</td><td><button className="text-btn" onClick={() => navigate(`/tasks/${item.id}/flow`)}>继续 <ChevronRight size={14} /></button></td></tr>)}</tbody></table></div></Panel><Panel title="待处理事项" meta="可恢复"><div className="queue-list"><div><span className="queue-icon amber"><ClipboardCheck size={16} /></span><div><strong>{state.tasks.some(item => item.status === 'review') ? '有任务等待审核' : '计划节点待人工确认'}</strong><small>低置信度资产不自动执行</small></div><ChevronRight size={16} /></div><div><span className="queue-icon blue"><Database size={16} /></span><div><strong>数据质检快照已保存</strong><small>来源、时间和质量状态可追溯</small></div><ChevronRight size={16} /></div></div></Panel></div></Page> }

function NewTask() { const { dispatch } = useDemo(); const navigate = useNavigate(); const [name, setName] = useState(''); const [well, setWell] = useState(''); const [error, setError] = useState(''); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!name.trim() || !well.trim()) { setError('任务名称和目标井为必填项'); return } dispatch({ type: 'createTask', name: name.trim(), well: well.trim() }); navigate('/workspace') }; return <Page eyebrow="PAGE-001 · FUNC-006" title="新建评价任务" actions={<button className="button secondary" onClick={() => navigate('/workspace')}>取消</button>}><div className="form-layout"><Panel title="任务信息" meta="创建后可保存为草稿"><form onSubmit={submit} className="form"><label>任务名称<input aria-label="任务名称" value={name} onChange={event => setName(event.target.value)} placeholder="例如：东区示例井 DST 评价" /></label><label>目标井 / 批次<input aria-label="目标井" value={well} onChange={event => setWell(event.target.value)} placeholder="例如：AQ-07-015" /></label><label>评价类型<select aria-label="评价类型" defaultValue="dst"><option value="dst">单井 DST 产能评价</option><option value="batch">多井批量（Demo 占位）</option></select></label><div className="data-source"><Database size={18} /><div><strong>Demo 数据源</strong><span>稳定虚构快照 · 2026-07-23 · 质检通过</span></div><span className="status green">可用</span></div>{error && <div className="field-error" role="alert"><XCircle size={15} />{error}</div>}<button className="button primary" type="submit"><CheckCircle2 size={16} />创建草稿</button></form></Panel><Panel title="创建边界" meta="TBD"><ul className="plain-list"><li><CheckCircle2 size={15} />仅创建本地 Demo 任务，不读取文件或数据湖</li><li><ShieldAlert size={15} />正式公式、图版和报告模板未批准，结果显示 TBD</li><li><History size={15} />任务版本和操作会写入本地审计列表</li></ul></Panel></div></Page> }

function useTask() { const { id } = useParams(); const { state } = useDemo(); return state.tasks.find(item => item.id === id) || state.tasks.find(item => item.id === state.activeTaskId) || state.tasks[0] }
function Flow() { const { state, dispatch } = useDemo(); const task = useTask(); const navigate = useNavigate(); if (!task) return <Empty title="没有可恢复任务" action={<button className="button primary" onClick={() => navigate('/tasks/new')}>创建任务</button>} />; const next = task.nodes.find(node => node.status === 'pending' || node.status === 'running'); const canApprove = state.role === 'reviewer' || state.role === 'admin'; return <Page eyebrow="PAGE-003 · FLOW-001/002/003/004" title={task.name} actions={<><button className="button secondary" onClick={() => navigate(`/tasks/${task.id}/analysis`)}><BarChart3 size={16} />查看分析</button><button className="button primary" onClick={() => dispatch({ type: 'setTaskStatus', taskId: task.id, status: task.status === 'paused' ? 'running' : 'paused' })}>{task.status === 'paused' ? <Play size={16} /> : <Activity size={16} />}{task.status === 'paused' ? '恢复' : '暂停'}</button></>}><div className="flow-layout"><Panel title="任务状态" meta={`版本 v${task.version}`}><div className="task-status-line"><Status status={task.status} /><span className="muted">目标井 {task.well} · 数据快照 DS-2026-0723</span></div><div className="node-list">{task.nodes.map((node, index) => <div className={`node-row ${node.status}`} key={node.id}><div className="node-index">{node.status === 'confirmed' ? <CheckCircle2 size={17} /> : node.status === 'blocked' ? <ShieldAlert size={17} /> : index + 1}</div><div className="node-copy"><strong>{node.label}</strong><small>{node.func} · {node.note || (node.status === 'pending' ? '等待确认' : '可继续')}</small></div><span className={`node-tag ${node.status}`}>{node.status === 'confirmed' ? '已确认' : node.status === 'blocked' ? '阻断 · TBD' : node.status === 'running' ? '进行中' : '待确认'}</span>{node.status === 'pending' && node === next && <button className="text-btn" onClick={() => dispatch({ type: 'confirmNode', taskId: task.id, nodeId: node.id })}>确认节点</button>}</div>)}</div><div className="action-row"><button className="button secondary" onClick={() => dispatch({ type: 'setTaskStatus', taskId: task.id, status: 'cancelled' })}><XCircle size={16} />取消并保留草稿</button>{task.status === 'rejected' && <button className="button primary" onClick={() => dispatch({ type: 'resubmitTask', taskId: task.id })}>修改后重提</button>}{task.status === 'running' && <button className="button primary" onClick={() => dispatch({ type: 'setTaskStatus', taskId: task.id, status: 'review' })} disabled={!canApprove}>提交审核</button>}</div></Panel><Panel title="人工确认点" meta="DEC-006"><div className="callout warning"><ShieldAlert size={17} /><div><strong>公式/图版、敏感性和正式报告结果均为 TBD</strong><p>Demo 只演示确认动作、阻断和可恢复路径，不生成业务数值。</p></div></div><div className="candidate-list"><div><span>推荐资产</span><strong>公式候选 A · v0.0-demo</strong><small>适用范围：占位；审批状态：未批准</small></div><div><span>用户决定</span><strong>等待审核人确认</strong><small>多候选或低置信度不会自动推进</small></div></div></Panel></div></Page> }

function Analysis() { const task = useTask(); const navigate = useNavigate(); const { state } = useDemo(); if (!task) return <Empty title="没有可分析任务" />; return <Page eyebrow="PAGE-005 · FUNC-019/021/023" title="图表与分析" actions={<button className="button secondary" onClick={() => navigate(`/tasks/${task.id}/trace`)}><History size={16} />查看溯源</button>}><div className="analysis-grid"><Panel title="DST 归一化演示图" meta="Demo 数据 · 不代表业务结论" className="chart-panel"><div className="chart"><div className="chart-y">归一化值</div><div className="chart-area">{[34, 46, 40, 58, 52, 67, 61, 76, 72, 83].map((height, index) => <span key={index} style={{ height: `${height}%` }} title={`点 ${index + 1}`} />)}<div className="chart-line" /></div><div className="chart-x"><span>样本 01</span><span>样本 05</span><span>样本 10</span></div></div><div className="chart-legend"><span><i className="dot teal" />归一化样本</span><span><i className="dot orange" />拟合趋势（占位）</span></div></Panel><Panel title="结果摘要" meta="方法版本 TBD"><div className="result-grid"><div><span>拟合参数</span><strong>TBD</strong><small>等待批准公式与金标准</small></div><div><span>敏感性范围</span><strong>TBD</strong><small>算法、范围尚未确认</small></div><div><span>目标井</span><strong>{task.well}</strong><small>来源：Demo 快照</small></div><div><span>方法差异</span><strong>待确认</strong><small>不生成正式产量结论</small></div></div><div className="callout info"><Sparkles size={17} /><div><strong>AI 解释（Mock）</strong><p>数据点和趋势仅用于走查图表交互。正式解释需要关联批准规则、知识引用和人工决定。</p></div></div></Panel></div><Panel title="样本明细" meta="可追溯到虚构快照"><div className="table-wrap"><table><thead><tr><th>样本</th><th>归一化 X</th><th>归一化 Y</th><th>状态</th><th>来源</th></tr></thead><tbody>{Array.from({ length: 5 }, (_, index) => <tr key={index}><td>DS-{String(index + 1).padStart(2, '0')}</td><td>{(0.18 + index * 0.12).toFixed(2)}</td><td>{(0.34 + index * 0.1).toFixed(2)}</td><td><span className="status green">可用</span></td><td>Mock fixture</td></tr>)}</tbody></table></div></Panel><div className="bottom-note"><AlertTriangle size={15} />{state.scenario === 'boundary' ? '边界场景：极值样本仅用于验证布局和状态反馈。' : '图表数值为稳定虚构归一化数据，不能用于实际产能评价。'}</div></Page> }

function Trace() { const task = useTask(); if (!task) return <Empty title="没有可查看版本" />; const rows = [['数据快照', 'DS-2026-0723', '已确认'], ['质检规则', 'Q-001-demo', 'Mock'], ['公式/图版', '待批准资产', 'TBD'], ['节点结果', `v${task.version}`, '可重现'], ['知识引用', 'KB-DEMO-004', '可访问 Mock'], ['人工决定', 'AUD-001～', '本地审计'], ['报告版本', '草稿', task.status === 'approved' ? '已批准' : '未发布']]; return <Page eyebrow="PAGE-006 · REQ-004/029/030" title="版本与全链路溯源"><div className="trace-head"><div><span className="eyebrow">{task.id}</span><h2>{task.name}</h2><p>任务版本 v{task.version} · {task.well}</p></div><span className="status blue">证据链完整（Mock）</span></div><Panel title="证据链" meta="数据 → 资产 → 节点 → 引用 → 决定 → 报告"><div className="trace-list">{rows.map(([label, value, status]) => <div key={label}><span className="trace-index"><CheckCircle2 size={15} /></span><div><strong>{label}</strong><small>{value}</small></div><span className="muted">{status}</span><ChevronRight size={15} /></div>)}</div></Panel><Panel title="操作记录" meta="本地 Demo 审计"><div className="audit-list">{useDemo().state.audit.map(event => <div key={event.id}><span>{event.at}</span><strong>{event.label}</strong><code>{event.id}</code></div>)}</div></Panel></Page> }

