function Reports() { const { state, dispatch } = useDemo(); const task = state.tasks.find(item => item.status === 'review' || item.status === 'rejected' || item.status === 'approved') || state.tasks[0]; if (!rolePages[state.role].includes('reports') || state.scenario === 'unauthorized') return <Unauthorized />; return <Page eyebrow="PAGE-007 · FUNC-025/026/027" title="报告中心"><div className="report-banner"><FileCheck2 size={19} /><div><strong>Demo 报告草稿</strong><span>正式模板和发布渠道为 TBD · 不可作为生产报告</span></div><span className="status amber">草稿</span></div><Panel title="审核队列" meta="审批链可追溯"><div className="report-review"><div><span>任务</span><strong>{task.name}</strong><small>{task.id} · v{task.version}</small></div><div><span>状态</span><Status status={task.status} /></div><div><span>审核意见</span><strong>{task.rejection || '等待审核人确认'}</strong></div></div><div className="action-row">{task.status === 'review' && (state.role === 'reviewer' || state.role === 'admin') && <><button className="button primary" onClick={() => dispatch({ type: 'setTaskStatus', taskId: task.id, status: 'approved' })}><CheckCircle2 size={16} />批准草稿</button><button className="button danger" onClick={() => dispatch({ type: 'rejectTask', taskId: task.id, reason: '请补充公式版本和差异解释证据' })}><XCircle size={16} />驳回并要求修改</button></>}{task.status === 'rejected' && <button className="button primary" onClick={() => dispatch({ type: 'resubmitTask', taskId: task.id })}>修改后重新提交</button>}{task.status === 'approved' && <span className="status green"><CheckCircle2 size={15} />已批准（Demo）</span>}</div></Panel><Panel title="报告内容预览" meta="字段均来自 Demo 状态"><div className="report-outline"><span>01</span><div><strong>任务摘要</strong><p>目标井 {task.well} · 数据快照 DS-2026-0723</p></div><span>TBD</span><div><strong>产能结论</strong><p>正式公式、图版、敏感性和多方法差异尚未批准</p></div></div></Panel></Page> }

