import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'
export default defineConfig({ plugins: [react()], test: { environment: 'jsdom', include: ['src/**/*.test.ts'] } })

import { describe, expect, it } from 'vitest'
import { demoTask, initialState } from './fixtures'
import { reducer } from './state'

describe('Demo reducer', () => {
  it('creates a draft task and records an audit event', () => {
    const state = reducer(initialState, { type: 'createTask', name: '测试任务', well: 'AQ-TEST-01' })
    expect(state.tasks[0].status).toBe('draft')
    expect(state.tasks[0].well).toBe('AQ-TEST-01')
    expect(state.audit[0].label).toContain('创建任务')
  })
  it('confirms a node and advances the next pending node', () => {
    const state = reducer(initialState, { type: 'confirmNode', taskId: demoTask.id, nodeId: 'dst' })
    const task = state.tasks.find(item => item.id === demoTask.id)!
    expect(task.nodes.find(node => node.id === 'dst')?.status).toBe('confirmed')
    expect(task.nodes.find(node => node.id === 'perm')?.status).toBe('running')
  })
  it('supports reject and resubmit without deleting history', () => {
    const rejected = reducer(initialState, { type: 'rejectTask', taskId: demoTask.id, reason: '补充证据' })
    expect(rejected.tasks[0].status).toBe('rejected')
    expect(rejected.tasks[0].rejection).toBe('补充证据')
    const resubmitted = reducer(rejected, { type: 'resubmitTask', taskId: demoTask.id })
    expect(resubmitted.tasks[0].status).toBe('review')
    expect(resubmitted.tasks[0].version).toBe(3)
  })
  it('resets all local state to stable fixtures', () => {
    const changed = reducer(initialState, { type: 'setScenario', scenario: 'error' })
    expect(reducer(changed, { type: 'reset' })).toEqual(initialState)
  })
})

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const file = readFileSync(resolve('TRACEABILITY.md'), 'utf8')
const required = ['REQ-001', 'REQ-002', 'REQ-003', 'REQ-004', 'REQ-005', 'REQ-006', 'REQ-007', 'REQ-008', 'REQ-009', 'REQ-010', 'REQ-011', 'REQ-012', 'REQ-013', 'REQ-014', 'REQ-015', 'REQ-016', 'REQ-017', 'REQ-018', 'REQ-019', 'REQ-020', 'REQ-021', 'REQ-022', 'REQ-023', 'REQ-024', 'REQ-025', 'REQ-026', 'REQ-027', 'REQ-028', 'REQ-029', 'REQ-030', 'REQ-031', 'REQ-035', 'REQ-036', 'REQ-037', 'REQ-038']
const missing = required.filter(id => !file.includes(id))
if (missing.length) { console.error(`Missing traceability IDs: ${missing.join(', ')}`); process.exit(1) }
