import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import mermaid from 'mermaid'

const docs = resolve('..', 'Project_Discovery')
const files = readdirSync(docs).filter(name => name.endsWith('.md'))
let count = 0
for (const name of files) {
  const source = readFileSync(resolve(docs, name), 'utf8')
  const blocks = [...source.matchAll(/```mermaid\s*([\s\S]*?)```/g)]
  for (let index = 0; index < blocks.length; index += 1) {
    try { await mermaid.parse(blocks[index][1]); count += 1 } catch (error) { console.error(`${name} mermaid block ${index + 1} failed:`, error); process.exit(1) }
  }
}
if (count === 0) { console.error('No Mermaid blocks found'); process.exit(1) }
console.log(`Mermaid parse OK: ${count} blocks across 00-13 documents.`)

import { expect, test } from '@playwright/test'
import { mkdirSync } from 'node:fs'
import { resolve } from 'node:path'

const evidence = resolve('..', 'reports', 'evidence')
mkdirSync(evidence, { recursive: true })
for (const width of [1440, 1280, 1024, 390]) {
  test(`workspace layout ${width}px has no global overflow`, async ({ page }) => {
    const errors: string[] = []
    page.on('console', message => { if (message.type() === 'error') errors.push(message.text()) })
    page.on('pageerror', error => errors.push(error.message))
    await page.setViewportSize({ width, height: width === 390 ? 844 : 900 })
    await page.goto('/workspace')
    await expect(page.getByRole('heading', { name: '产能评价工作台' })).toBeVisible()
    expect(await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth)).toBe(false)
    await page.screenshot({ path: resolve(evidence, `workspace-${width}.png`), fullPage: true })
    expect(errors).toEqual([])
  })
}
test('keyboard focus and basic accessibility checks', async ({ page }) => {
  await page.goto('/workspace')
  await page.keyboard.press('Tab')
  expect(['BUTTON', 'A', 'SELECT']).toContain(await page.evaluate(() => document.activeElement?.tagName))
  const violations = await page.evaluate(() => {
    const issues: string[] = []
    document.querySelectorAll('button').forEach((button, index) => { if (!(button.textContent?.trim() || button.getAttribute('aria-label') || button.getAttribute('title'))) issues.push(`button-${index}`) })
    document.querySelectorAll('input, textarea, select').forEach((control, index) => { if (!control.getAttribute('aria-label') && !control.closest('label')) issues.push(`control-${index}`) })
    if (!document.querySelector('h1')) issues.push('missing-h1')
    return issues
  })
  expect(violations).toEqual([])
})

