import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { chromium } from '@playwright/test'

const docs = resolve('..', 'Project_Discovery')
const files = readdirSync(docs).filter(name => name.endsWith('.md'))
const entries = []
for (const name of files) {
  const source = readFileSync(resolve(docs, name), 'utf8')
  for (const [index, block] of [...source.matchAll(/```mermaid\s*([\s\S]*?)```/g)].entries()) entries.push({ name, index: index + 1, graph: block[1] })
}
if (entries.length === 0) { console.error('No Mermaid blocks found'); process.exit(1) }
const browser = await chromium.launch({ channel: 'chrome', headless: true })
try {
  const page = await browser.newPage()
  await page.setContent('<!doctype html><html><body></body></html>')
  await page.addScriptTag({ path: resolve('node_modules', 'mermaid', 'dist', 'mermaid.min.js') })
  for (const entry of entries) {
    try { await page.evaluate(async graph => { window.mermaid.initialize({ startOnLoad: false, securityLevel: 'strict' }); await window.mermaid.parse(graph) }, entry.graph) }
    catch (error) { console.error(`${entry.name} mermaid block ${entry.index} failed:`, error); process.exitCode = 1; break }
  }
  if (!process.exitCode) console.log(`Mermaid parse OK: ${entries.length} blocks across 00-13 documents in local Chrome.`)
} finally { await browser.close() }

